	private static final class Harness implements AutoCloseable {
		final Source source = new Source();
		final RuntimeException timeout;
		final AtomicInteger attempts = new AtomicInteger();
		final AtomicReference<Throwable> first = new AtomicReference<>(), fallback = new AtomicReference<>();
		final AtomicReference<Throwable> firstLaterError = new AtomicReference<>();
		final CountDownLatch retryEntered = new CountDownLatch(1), releaseRetry = new CountDownLatch(1);
		final CopyOnWriteArrayList<Task<?>> tasks = new CopyOnWriteArrayList<>();
		final CopyOnWriteArrayList<TimeLimitIteration<String>> extraIterations = new CopyOnWriteArrayList<>();
		final TimeLimitIteration<String> limited;

		Harness(boolean disableSuppression, boolean holdRetry) {
			this(disableSuppression, holdRetry, false);
		}

		Harness(boolean disableSuppression, boolean holdRetry, boolean laterError) {
			this(disableSuppression, holdRetry, laterError, false);
		}

		Harness(boolean disableSuppression, boolean holdRetry, boolean laterError, boolean cyclicError) {
			this(disableSuppression, holdRetry, laterError, cyclicError, false, false, false);
		}

		Harness(boolean disableSuppression, boolean holdRetry, boolean laterError, boolean cyclicError,
				boolean largeGraph, boolean throwingCause, boolean closeFails) {
			if (closeFails)
				source.closeFailure = new IllegalStateException("source close failure");
			timeout = disableSuppression ? new NoSuppressionTimeout() : new IllegalStateException("timed out");
			TimeLimitIteration.AsyncLauncher launcher = action -> {
				int number = attempts.incrementAndGet();
				RejectedExecutionException failure = throwingCause && number == 1
						? new ThrowingCauseFailure()
						: new RejectedExecutionException("launch failure " + number);
				if (largeGraph && number == 1)
					failure.initCause(deepGraph());
				if (number == 1)
					first.set(failure);
				if (number == 2)
					fallback.set(failure);
				if (laterError && number == 3) {
					AssertionError fatal = new AssertionError("later fatal launch failure");
					firstLaterError.set(fatal);
					throw fatal;
				}
				if (cyclicError && number == 5) {
					AssertionError fatal = new AssertionError("later cyclic launch failure", timeout);
					firstLaterError.set(fatal);
					throw fatal;
				}
				if (holdRetry && number == 3) {
					retryEntered.countDown();
					await(releaseRetry);
				}
				throw failure;
			};
			limited = new TimeLimitIteration<>(source, 60_000, launcher) {
				@Override
				protected void throwInterruptedException() {
					throw timeout;
				}
			};
		}

		long additionalPairs() {
			assertEquals(0, attempts.get() % 2, "both launch attempts must have completed");
			return attempts.get() / 2L - 1;
		}

		void checkTimeouts(int count) throws Exception {
			for (int i = 0; i < count; i++)
				assertSame(timeout, outcome(start("check", limited::hasNext)));
		}

		Throwable closeResult() throws Exception {
			return outcome(start("close", () -> {
				limited.close();
				return null;
			}));
		}

		<T> Task<T> start(String name, Callable<T> action) {
			FutureTask<T> future = new FutureTask<>(action);
			Thread thread = Thread.ofVirtual().name("bounded-launch-" + name).unstarted(future);
			Task<T> task = new Task<>(future, thread);
			tasks.add(task);
			thread.start();
			return task;
		}

		<T> Task<T> startPlatform(String name, Callable<T> action) {
			FutureTask<T> future = new FutureTask<>(action);
			Thread thread = Thread.ofPlatform().daemon().name("bounded-launch-" + name).unstarted(future);
			Task<T> task = new Task<>(future, thread);
			tasks.add(task);
			thread.start();
			return task;
		}

		Throwable outcome(Task<?> task) throws Exception {
			Throwable failure = awaitTask(task.future);
			task.consumed = true;
			return failure;
		}

		@Override
		public void close() throws Exception {
			releaseRetry.countDown();
			start("cleanup-close", () -> {
				limited.close();
				return null;
			});
			for (TimeLimitIteration<String> extra : extraIterations) {
				start("cleanup-extra", () -> {
					extra.close();
					return null;
				});
			}
			Throwable failure = null;
			for (int i = 0; i < tasks.size(); i++) {
				Task<?> task = tasks.get(i);
				try {
					Throwable problem = awaitTask(task.future);
					if (!task.consumed && problem != null)
						failure = combine(failure, problem);
					task.thread.join(3000);
					if (task.thread.isAlive()) {
						failure = combine(failure, new AssertionError("completed test task thread did not exit"));
					}
				} catch (TimeoutException unresolved) {
					System.err.println("UNRESOLVED_TEST_THREAD thread=" + task.thread + " stack="
							+ java.util.Arrays.toString(task.thread.getStackTrace()));
					failure = combine(failure, new AssertionError("test-owned thread did not finish", unresolved));
				}
			}
			if (failure instanceof Exception exception)
				throw exception;
			if (failure instanceof Error error)
				throw error;
		}
	}

	private static final class Task<T> {
		final FutureTask<T> future;
		final Thread thread;
		boolean consumed;

		Task(FutureTask<T> future, Thread thread) {
			this.future = future;
			this.thread = thread;
		}
	}

	private static Throwable awaitTask(FutureTask<?> future) throws Exception {
		try {
			future.get(3, TimeUnit.SECONDS);
			return null;
		} catch (ExecutionException failure) {
			return failure.getCause();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(10, TimeUnit.SECONDS))
				throw new AssertionError("retry release was not reached");
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError("retry interrupted", failure);
		}
	}

	private static boolean awaitBlockedReport(Thread thread, long expectedOwner) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (System.nanoTime() < deadline) {
			ThreadInfo info = ManagementFactory.getThreadMXBean().getThreadInfo(thread.getId(), Integer.MAX_VALUE);
			if (info != null && info.getThreadState() == Thread.State.BLOCKED
					&& (expectedOwner < 0 || info.getLockOwnerId() == expectedOwner)
					&& java.util.Arrays.stream(info.getStackTrace())
							.anyMatch(frame -> frame.getClassName().equals(TimeLimitIteration.class.getName())
									&& frame.getMethodName().equals("includeLaunchFailures")))
				return true;
			Thread.onSpinWait();
		}
		return false;
	}

	private static void assertFirstFailuresVisible(Throwable outcome, Harness h) {
		assertNotNull(h.first.get());
		assertNotNull(h.fallback.get());
		Set<Throwable> seen = graph(outcome);
		assertTrue(seen.contains(h.first.get()), "first launch failure must remain reachable by identity");
		assertTrue(seen.contains(h.fallback.get()), "first fallback failure must remain reachable by identity");
	}

	private static void assertAdditionalFailuresVisible(Throwable outcome, long count) {
		assertTrue(graph(outcome).stream()
				.map(Throwable::getMessage)
				.filter(java.util.Objects::nonNull)
				.map(message -> message.toLowerCase(Locale.ROOT))
				.anyMatch(message -> message.contains("additional") && message.contains(Long.toString(count))),
				"the diagnostic must report " + count + " additional failed launch pairs");
	}

	private static void assertRecognizedClose(Throwable outcome, Harness h) {
		if (outcome != null)
			assertFirstFailuresVisible(outcome, h);
	}

	private static Set<Throwable> graph(Throwable root) {
		Set<Throwable> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		if (root == null)
			return seen;
		ArrayDeque<Throwable> pending = new ArrayDeque<>();
		pending.add(root);
		while (!pending.isEmpty()) {
			Throwable current = pending.remove();
			if (!seen.add(current))
				continue;
			if (current.getCause() != null)
				pending.add(current.getCause());
			Collections.addAll(pending, current.getSuppressed());
		}
		return seen;
	}

	private static Throwable combine(Throwable primary, Throwable secondary) {
		if (primary == null)
			return secondary;
		if (primary != secondary)
			primary.addSuppressed(secondary);
		return primary;
	}

	private static Throwable deepGraph() {
		Throwable result = null;
		for (int i = 0; i < 2048; i++)
			result = new RuntimeException("external cause " + i, result);
		return result;
	}

	private static final class ThrowingCauseFailure extends RejectedExecutionException {
		@Override
		public synchronized Throwable getCause() {
			throw new IllegalStateException("cause inspection failed");
		}
	}

	private static final class NoSuppressionTimeout extends RuntimeException {
		NoSuppressionTimeout() {
			super("timed out", null, false, true);
		}
	}

	private static final class Source implements CloseableIteration<String>, CooperativeCancellation {
		final AtomicInteger requests = new AtomicInteger(), closes = new AtomicInteger();
		RuntimeException closeFailure;
		final CountDownLatch callbackEntered = new CountDownLatch(1), closeFinished = new CountDownLatch(1);

		@Override
		public boolean hasNext() {
			throw new AssertionError("timed out source must not be entered");
		}

		@Override
		public String next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean requestCancellation() {
			requests.incrementAndGet();
			callbackEntered.countDown();
			return true;
		}

		@Override
		public void close() {
			closes.incrementAndGet();
			closeFinished.countDown();
			if (closeFailure != null)
				throw closeFailure;
		}
	}
